import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
enum WorldTheme { garden, tree, path, pond, kitchen, pantry }
class NutriWorldState { const NutriWorldState({this.garden=0,this.tree=0,this.path=0,this.pond=0,this.kitchen=0,this.pantry=0}); final int garden,tree,path,pond,kitchen,pantry; int value(WorldTheme t)=>switch(t){WorldTheme.garden=>garden,WorldTheme.tree=>tree,WorldTheme.path=>path,WorldTheme.pond=>pond,WorldTheme.kitchen=>kitchen,WorldTheme.pantry=>pantry}; NutriWorldState add(WorldTheme t,[int amount=1])=>NutriWorldState(garden:garden+(t==WorldTheme.garden?amount:0),tree:tree+(t==WorldTheme.tree?amount:0),path:path+(t==WorldTheme.path?amount:0),pond:pond+(t==WorldTheme.pond?amount:0),kitchen:kitchen+(t==WorldTheme.kitchen?amount:0),pantry:pantry+(t==WorldTheme.pantry?amount:0));}
class NutriWorldRepository { NutriWorldRepository(this.preferences); final SharedPreferences preferences; static const key='nutri-world.v1'; NutriWorldState load(){final raw=preferences.getString(key);if(raw==null)return const NutriWorldState();try{final m=jsonDecode(raw) as Map;return NutriWorldState(garden:m['garden']??0,tree:m['tree']??0,path:m['path']??0,pond:m['pond']??0,kitchen:m['kitchen']??0,pantry:m['pantry']??0);}catch(_){return const NutriWorldState();}} Future<void> award(WorldTheme theme,[int amount=1])async{final s=load().add(theme,amount);final ok=await preferences.setString(key,jsonEncode({'garden':s.garden,'tree':s.tree,'path':s.path,'pond':s.pond,'kitchen':s.kitchen,'pantry':s.pantry}));if(!ok)throw StateError('NutriWorld konnte nicht gespeichert werden.');}}
